  "inlineSchema": "// Prisma Schema for Pig Farm Management System\n// Comprehensive schema matching frontend requirements\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ============ ANIMALS ============\nmodel Animal {\n  id             String    @id @default(cuid())\n  tagNo          String    @unique\n  name           String?\n  type           String // 'sow', 'boar', 'piglet'\n  breed          String?\n  dob            DateTime?\n  weight         Float?\n  weightHistory  Json? // array of {date, weight}\n  litterNo       String?\n  stage          String? // 'grower', 'finisher', etc\n  status         String? // 'active', 'sold', 'deceased'\n  entryDate      DateTime?\n  obtainedMethod String? // 'Bred On Farm', 'Purchased', etc\n  source         String?\n  motherTag      String?\n  fatherTag      String?\n  group          String?\n  imageUrl       String?\n  notes          String?\n  createdAt      DateTime  @default(now())\n  updatedAt      DateTime  @updatedAt\n\n  // Relations\n  healthRecords HealthRecord[]\n  events        Event[]\n  pregnancies   Pregnancy[]    @relation(\"SowPregnancies\")\n  asBoar        Pregnancy[]    @relation(\"BoarBreedings\")\n\n  @@index([type])\n  @@index([tagNo])\n  @@index([status])\n}\n\n// ============ HEALTH ============\nmodel HealthRecord {\n  id           String    @id @default(cuid())\n  animalId     String\n  animal       Animal    @relation(fields: [animalId], references: [id], onDelete: Cascade)\n  date         DateTime  @default(now())\n  type         String // 'checkup', 'vaccination', 'treatment', 'injury', 'illness'\n  condition    String? // 'healthy', 'sick', 'recovering'\n  treatment    String?\n  medication   String?\n  veterinarian String?\n  cost         Float?\n  notes        String?\n  followUpDate DateTime?\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  @@index([animalId])\n  @@index([date])\n}\n\n// ============ BREEDING & PREGNANCY ============\nmodel Pregnancy {\n  id                String    @id @default(cuid())\n  sowId             String\n  sow               Animal    @relation(\"SowPregnancies\", fields: [sowId], references: [id], onDelete: Cascade)\n  boarId            String?\n  boar              Animal?   @relation(\"BoarBreedings\", fields: [boarId], references: [id])\n  dateServed        DateTime\n  expectedFarrowing DateTime // dateServed + 114 days\n  actualFarrowing   DateTime?\n  status            String    @default(\"pregnant\") // 'pregnant', 'farrowed', 'failed'\n  notes             String?\n  createdAt         DateTime  @default(now())\n  updatedAt         DateTime  @updatedAt\n\n  // Linked litter\n  litter Litter?\n\n  @@index([sowId])\n  @@index([status])\n  @@index([expectedFarrowing])\n}\n\n// ============ LITTERS ============\nmodel Litter {\n  id            String    @id @default(cuid())\n  pregnancyId   String    @unique\n  pregnancy     Pregnancy @relation(fields: [pregnancyId], references: [id], onDelete: Cascade)\n  farrowDate    DateTime\n  numberBorn    Int\n  alive         Int\n  dead          Int\n  weaningDate   DateTime?\n  weaningWeight Float?\n  notes         String?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  @@index([farrowDate])\n}\n\n// ============ EVENTS ============\nmodel Event {\n  id          String    @id @default(cuid())\n  animalId    String?\n  animal      Animal?   @relation(fields: [animalId], references: [id], onDelete: Cascade)\n  type        String // 'breeding', 'health', 'weight', 'movement', 'sale', etc\n  date        DateTime  @default(now())\n  description String?\n  semen       String? // for breeding events\n  technician  String?\n  returnDate  DateTime? // for heat/breeding cycles\n  metadata    Json? // flexible field for additional data\n  notes       String?\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  @@index([animalId])\n  @@index([type])\n  @@index([date])\n}\n\n// ============ FEED ============\nmodel FeedType {\n  id           String   @id @default(cuid())\n  name         String   @unique\n  category     String // 'starter', 'grower', 'finisher', 'sow'\n  costPerUnit  Float\n  unit         String // 'kg', 'bag'\n  description  String?\n  inventory    Float    @default(0)\n  lowThreshold Float?\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  usageLogs FeedLog[]\n}\n\nmodel FeedLog {\n  id         String   @id @default(cuid())\n  feedTypeId String\n  feedType   FeedType @relation(fields: [feedTypeId], references: [id], onDelete: Cascade)\n  quantity   Float // amount used (negative) or added (positive)\n  reason     String // 'daily_feed', 'purchase', 'adjustment'\n  groupType  String? // 'sows', 'boars', 'piglets', 'growers'\n  date       DateTime @default(now())\n  notes      String?\n  createdAt  DateTime @default(now())\n\n  @@index([feedTypeId])\n  @@index([date])\n}\n\n// ============ FINANCE ============\nmodel Cost {\n  id          String   @id @default(cuid())\n  category    String // 'feed', 'veterinary', 'labor', 'housing', 'utilities', 'transport', 'other'\n  amount      Float\n  description String?\n  date        DateTime @default(now())\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@index([category])\n  @@index([date])\n}\n\nmodel Sale {\n  id           String   @id @default(cuid())\n  animalTag    String? // reference to animal tagNo\n  type         String // 'piglet', 'boar', 'sow', 'meat'\n  quantity     Int      @default(1)\n  pricePerUnit Float\n  totalAmount  Float\n  buyer        String?\n  date         DateTime @default(now())\n  notes        String?\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  @@index([date])\n  @@index([type])\n}\n\n// ============ INVENTORY ============\nmodel InventoryItem {\n  id           String   @id @default(cuid())\n  name         String\n  category     String // 'medication', 'equipment', 'supplies'\n  quantity     Float\n  unit         String // 'pieces', 'liters', 'kg'\n  costPerUnit  Float?\n  supplier     String?\n  lowThreshold Float?\n  notes        String?\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  @@index([category])\n}\n",
